module xorbonacci (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire query,\n    input wire [7:0] a0, a1, a2, a3,\n    input wire [15:0] l, r,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State encoding\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] LOADING = 3'd1;\n    localparam [2:0] READY = 3'd2;\n    localparam [2:0] COMPUTING = 3'd3;\n    localparam [2:0] RESULT = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state;\n    reg [7:0] P [0:4];           // Prefix XOR table\n    reg [15:0] l_reg, r_reg;    // Stored query indices\n    reg [2:0] rem_l, rem_r;     // Remainders modulo 5\n    integer i;\n\n    // Helper function: compute 16-bit value modulo 5\n    function [2:0] mod5;\n        input [15:0] val;\n        reg [4:0] sum_low, sum_high;\n        reg [4:0] rlow, rhigh;\n        begin\n            sum_low = val[7:4] + val[3:0];\n            rlow = sum_low;\n            if (rlow >= 25)      rlow = rlow - 25;\n            else if (rlow >= 20) rlow = rlow - 20;\n            else if (rlow >= 15) rlow = rlow - 15;\n            else if (rlow >= 10) rlow = rlow - 10;\n            else if (rlow >= 5)  rlow = rlow - 5;\n\n            sum_high = val[15:12] + val[11:8];\n            rhigh = sum_high;\n            if (rhigh >= 25)      rhigh = rhigh - 25;\n            else if (rhigh >= 20) rhigh = rhigh - 20;\n            else if (rhigh >= 15) rhigh = rhigh - 15;\n            else if (rhigh >= 10) rhigh = rhigh - 10;\n            else if (rhigh >= 5)  rhigh = rhigh - 5;\n\n            mod5 = rhigh + rlow;\n            if (mod5 >= 5) mod5 = mod5 - 5;\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            l_reg <= 16'd0;\n            r_reg <= 16'd0;\n            rem_l <= 3'd0;\n            rem_r <= 3'd0;\n            for (i = 0; i < 5; i = i + 1) begin\n                P[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize prefix array\n                        P[0] <= 8'd0;\n                        P[1] <= a0;\n                        P[2] <= a0 ^ a1;\n                        P[3] <= (a0 ^ a1) ^ a2;\n                        P[4] <= ((a0 ^ a1) ^ a2) ^ a3;\n                        state <= LOADING;\n                    end\n                end\n                \n                LOADING: begin\n                    state <= READY;\n                end\n\n                READY: begin\n                    done <= 1'b0;\n                    if (query) begin\n                        l_reg <= l;\n                        r_reg <= r;\n                        state <= COMPUTING;\n                    end\n                end\n\n                COMPUTING: begin\n                    rem_l <= mod5(l_reg);      // (l mod5)\n                    rem_r <= mod5(r_reg + 16'd1); // (r+1 mod5)\n                    state <= RESULT;\n                end\n\n                RESULT: begin\n                    result <= P[rem_r] ^ P[rem_l];\n                    done <= 1'b1;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= READY;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule